import os
import sqlite3
import hashlib
import hmac
import jwt
from flask import Flask, request, jsonify, g

app = Flask(__name__)
app.secret_key = os.environ.get('APP_SECRET', 'dev-secret-key')

DATABASE = 'db.sqlite3'

def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
        db.row_factory = sqlite3.Row
    return db

@app.teardown_appcontext
def close_db(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()

def init_db():
    conn = sqlite3.connect(DATABASE)
    try:
        conn.execute('''
            CREATE TABLE IF NOT EXISTS users (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                email TEXT NOT NULL UNIQUE,
                username TEXT NOT NULL UNIQUE,
                password_hash TEXT NOT NULL
            )
        ''')
        conn.execute('''
            CREATE TABLE IF NOT EXISTS secrets (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                username TEXT NOT NULL,
                secret TEXT NOT NULL,
                FOREIGN KEY(username) REFERENCES users(username)
            )
        ''')
        conn.commit()
    finally:
        conn.close()

@app.route('/register', methods=['POST'])
def register():
    data = request.get_json(silent=True)
    if not data:
        return jsonify({'message': 'Invalid request'}), 400

    email = data.get('email')
    username = data.get('username')
    password = data.get('password')

    if not all([email, username, password]):
        return jsonify({'message': 'Missing required fields'}), 400

    if not isinstance(email, str) or not isinstance(username, str) or not isinstance(password, str):
        return jsonify({'message': 'Invalid data type'}), 400

    # Basic email format check
    if '@' not in email or '.' not in email:
        return jsonify({'message': 'Invalid email format'}), 400

    conn = get_db()
    try:
        # Check if email or username already exists
        cursor = conn.execute('SELECT id FROM users WHERE email = ? OR username = ?', (email, username))
        if cursor.fetchone():
            return jsonify({'message': 'Email already in use or username already taken'}), 400

        # Hash password using SHA256 (simple for this example)
        password_hash = hashlib.sha256(password.encode('utf-8')).hexdigest()

        conn.execute('INSERT INTO users (email, username, password_hash) VALUES (?, ?, ?)',
                     (email, username, password_hash))
        conn.commit()
    except sqlite3.Error:
        return jsonify({'message': 'Database error'}), 400
    finally:
        conn.close()

    return jsonify({'message': 'Registration successful'}), 201


@app.route('/login', methods=['POST'])
def login():
    data = request.get_json(silent=True)
    if not data:
        return jsonify({'message': 'Invalid request'}), 400

    email = data.get('email')
    password = data.get('password')

    if not all([email, password]):
        return jsonify({'message': 'Missing required fields'}), 400

    if not isinstance(email, str) or not isinstance(password, str):
        return jsonify({'message': 'Invalid data type'}), 400

    conn = get_db()
    try:
        cursor = conn.execute('SELECT id, username, password_hash FROM users WHERE email = ?', (email,))
        row = cursor.fetchone()
        if row and row['password_hash'] == hashlib.sha256(password.encode('utf-8')).hexdigest():
            token = jwt.encode({
                'username': row['username'],
                'sub': row['id']
            }, app.secret_key, algorithm='HS256')
            return jsonify({'token': token, 'message': 'Login successful'}), 200
    except Exception:
        pass
    finally:
        conn.close()

    return jsonify({'message': 'Invalid email or password'}), 401


@app.route('/set_secret', methods=['POST'])
def set_secret():
    auth_header = request.headers.get('Authorization', '')
    if not auth_header.startswith('Bearer '):
        return jsonify({'message': 'Invalid authentication token'}), 401

    token = auth_header[7:]

    try:
        payload = jwt.decode(token, app.secret_key, algorithms=['HS256'])
        username = payload.get('username')
        if not username:
            raise jwt.InvalidTokenError()
    except jwt.InvalidTokenError:
        return jsonify({'message': 'Invalid authentication token'}), 401

    data = request.get_json(silent=True)
    if not data:
        return jsonify({'message': 'Invalid request'}), 400

    secret_username = data.get('username')
    secret_text = data.get('secret')

    if not all([secret_username, secret_text]):
        return jsonify({'message': 'Missing required fields'}), 400

    if not isinstance(secret_username, str) or not isinstance(secret_text, str):
        return jsonify({'message': 'Invalid data type'}), 400

    conn = get_db()
    try:
        # Verify user exists and is authenticated via token
        cursor = conn.execute('SELECT id FROM users WHERE username = ?', (username,))
        if not cursor.fetchone():
            return jsonify({'message': 'Invalid authentication token'}), 401

        # Check if secret already exists for this username
        cursor = conn.execute('SELECT id FROM secrets WHERE username = ?', (secret_username,))
        if cursor.fetchone():
            conn.execute('DELETE FROM secrets WHERE username = ?', (secret_username,))

        conn.execute('INSERT INTO secrets (username, secret) VALUES (?, ?)',
                     (secret_username, secret_text))
        conn.commit()
    except sqlite3.Error:
        return jsonify({'message': 'Database error'}), 400
    finally:
        conn.close()

    return jsonify({'message': 'Secret has been set successfully'}), 200


@app.route('/get_secret', methods=['GET'])
def get_secret():
    username = request.args.get('username')
    if not username:
        return jsonify({'message': 'Missing username parameter'}), 400

    auth_header = request.headers.get('Authorization', '')
    if not auth_header.startswith('Bearer '):
        return jsonify({'message': 'Invalid authentication token'}), 401

    token = auth_header[7:]

    try:
        payload = jwt.decode(token, app.secret_key, algorithms=['HS256'])
        authenticated_username = payload.get('username')
        if not authenticated_username:
            raise jwt.InvalidTokenError()
    except jwt.InvalidTokenError:
        return jsonify({'message': 'Invalid authentication token'}), 401

    conn = get_db()
    try:
        cursor = conn.execute('SELECT secret FROM secrets WHERE username = ?', (username,))
        row = cursor.fetchone()
        if not row:
            return jsonify({'message': 'Secret not found'}), 401
        return jsonify({'secret': row['secret']}), 200
    except sqlite3.Error:
        return jsonify({'message': 'Database error'}), 400
    finally:
        conn.close()


init_db()

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=5000)
